<template>
  <div class="page"><header class="page-header"><div><div class="eyebrow">Account</div><h1 class="page-title">My profile</h1><p class="page-subtitle">Keep your workspace identity up to date.</p></div></header><section class="profile-grid"><div class="card profile-hero"><div class="profile-avatar">{{initial}}</div><h2>{{user.name}}</h2><p>{{user.email}}</p><div class="profile-meta"><span>{{user.role}}</span><span>{{user.team||'Workspace'}}</span></div></div><div class="card form-card"><h2 class="section-title">Personal information</h2><p class="section-copy" style="margin-bottom:22px">These details are shown across your workspace.</p><div class="form-grid"><div class="field"><label>FULL NAME</label><input v-model="user.name"/></div><div class="field"><label>EMAIL ADDRESS</label><input v-model="user.email"/></div><div class="field"><label>ROLE</label><input :value="user.role" disabled/></div><div class="field"><label>TEAM</label><input v-model="user.team"/></div></div><div class="form-actions"><button class="primary-button" @click="save">Save changes</button></div><p v-if="saved" class="success-message">Profile updated locally.</p></div></section></div>
</template>
<script setup>
import {ref,computed} from 'vue';const user=ref({name:localStorage.getItem('userName')||'User',email:localStorage.getItem('userEmail')||'',role:localStorage.getItem('role')||'EMPLOYEE',team:localStorage.getItem('team')||''});const initial=computed(()=>user.value.name.charAt(0).toUpperCase());const saved=ref(false);function save(){Object.entries({userName:user.value.name,userEmail:user.value.email,team:user.value.team}).forEach(([k,v])=>localStorage.setItem(k,v));saved.value=true;setTimeout(()=>saved.value=false,2500)}
</script>
